import requests

# Try to get the abstract from a different source
url = 'https://www.sciencedirect.com/science/article/abs/pii/S0213005X20300318'
headers = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
}

