        print('=== ScienceDirect Abstract ===')
        print(response.text[:2000])  # First 2000 characters
    else:
        print(f'ScienceDirect access failed: {response.status_code}')
except Exception as e:
    print(f'Error accessing ScienceDirect: {e}')

# Try another approach - search for the abstract text
print('\n=== Searching for abstract text ===')
